use filmcraft_project::{Project,ItemId};use filmcraft_media::{SharedSource,still::StillSource};use filmcraft_time::Tick;use filmcraft_render::{render_sequence,RenderOptions};use serde_json::{Value,json};use std::{sync::Arc,collections::BTreeMap};
fn main(){let mut cases=vec![];for (kind,path) in [("mask",std::env::args().nth(1).unwrap()),("nested",std::env::args().nth(2).unwrap())]{let fixture:Value=serde_json::from_slice(&std::fs::read(path).unwrap()).unwrap();for base in fixture["cases"].as_array().unwrap(){if kind=="mask"&&!(base["scale"]==1.&&base["shape"]==2&&base["profile"]==1){continue}
 for variant in 0..3{let mut doc=base["document"].clone();let mut rgba=BTreeMap::new();let mut sources=BTreeMap::new();for (key,item) in doc["project"]["items"].as_object_mut().unwrap(){let Some(media)=item.pointer_mut("/kind/Media")else{continue};let w=media["info"]["video"]["width"].as_u64().unwrap()as u32;let h=media["info"]["video"]["height"].as_u64().unwrap()as u32;
 let bytes:Vec<u8>=(0..w*h).flat_map(|i|[((i*37+11)%256)as u8,((i*73+51)%256)as u8,((i*19+83)%256)as u8,match variant{0=>255,1=>128,_=>[0,1,64,128,255][i as usize%5]}]).collect();let source=Arc::new(StillSource::from_rgba("pattern.png",w,h,bytes.clone(),true,0))as SharedSource;sources.insert(ItemId(key.parse().unwrap()),source);rgba.insert(key.clone(),json!({"width":w,"height":h,"pattern":variant}));media["media"]=json!({"File":{"path":"/original/pattern.png"}});}
 let p:Project=serde_json::from_value(doc["project"].clone()).unwrap();let provider=|id:ItemId|{let(root,_,_)=p.resolve_media(id)?;sources.get(&root).cloned()};let scales=if kind=="mask"{vec![1f32,0.5,0.25]}else{vec![base["scale"].as_f64().unwrap()as f32]};for scale in scales{let out=render_sequence(&p,ItemId(base["sequence"].as_u64().unwrap()),Tick(base["at"].as_i64().unwrap()),RenderOptions{scale,working_output:true,..Default::default()},&provider);cases.push(json!({"document":doc,"sequence":base["sequence"],"at":base["at"],"kind":kind,"variant":variant,"images":rgba,"scale":scale,"width":out.w,"height":out.h,"bits":out.px.iter().map(|v|v.to_bits()).collect::<Vec<_>>()}));}
 }
}}
println!("{}",json!({"commit":"5231852443363f001c3f6b396dd9b1e6461ae2be","cases":cases}));}
